<template>
    <div v-if="visible" class="login-expired-overlay" @click="clickOverlay">
        <div class="login-expired-dialog" @click.stop>
            <!-- 头部logo区域 -->
            <div class="dialog-header">
                <div class="logo-container">
                    <l-img
                        :src="appLogo"
                        w="60px"
                        h="60px"
                        class="logo-image"
                    />
                    <span class="logo-text">{{ appTitle }}</span>
                </div>
            </div>
            <!-- 关闭按钮 -->
            <button class="close-button" @click="clickClose">
                    <el-icon size="20px" color="#6B7280"><Close /></el-icon>
            </button>
            <!-- 警告提示区域 -->
            <div class="warning-section">
                <div class="warning-icon">
                    <l-img
                        src="/static/images/password-error.png"
                        w="18px"
                        h="18px"
                        class="warning-icon-img"
                    />
                </div>
                <span class="warning-text">{{ t('loginExpired') }}</span>
            </div>
            <!-- 登录表单区域 -->
            <div class="login-form">
                <div class="form-group">
                    <label class="form-label">{{ t('email') }}</label>
                    <div class="input-container">
                        <input
                            v-model="formData.email"
                            type="email"
                            class="form-input"
                            :class="{ 'input-error': errors.email }"
                            :placeholder="t('emailPlaceholder')"
                            @blur="validateEmail"
                            @input="clearEmailError"
                        />
                    </div>
                    <div v-if="errors.email" class="error-message">{{ errors.email }}</div>
                </div>

                <div class="form-group">
                    <label class="form-label">{{ t('password') }}</label>
                    <div class="password-container">
                        <div class="input-container">
                            <input
                                v-model="formData.password"
                                :type="showPassword ? 'text' : 'password'"
                                class="form-input"
                                :class="{ 'input-error': errors.password }"
                                :placeholder="t('passwordPlaceholder')"
                                @blur="validatePassword"
                                @input="clearPasswordError"
                            />
                            <button
                                type="button"
                                class="password-toggle"
                                @click="togglePassword"
                            >
                                <l-img
                                    :src="showPassword ? '/static/images/eye_icon2.png' : '/static/images/eye_icon1.png'"
                                    w="18px"
                                    h="18px"
                                    class="password-toggle-img"
                                />
                            </button>
                        </div>
                        <div v-if="errors.password" class="error-message">{{ errors.password }}</div>
                    </div>
                    <a href="#" class="forgot-password-link" @click.prevent="clickForgotPassword">
                        {{ t('forgotPassword') }}
                    </a>
                </div>

                <l-button
                    class="login-button"
                    :text="t('login')"
                    :loading-text="t('loggingIn')"
                    :loading="isLoading"
                    :disabled="isLoading || !isFormValid"
                    @onClick="clickLogin"
                    width="100%"
                    height="40px"
                    borderRadius="12px"
                    backgroundColor="#000000"
                    textColor="#FFFFFF"
                />
            </div>
        </div>
    </div>
</template>

<script setup>
import { ref, computed, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { ApiUser } from '@/api/api-user';
import { ElMessage } from 'element-plus';
import { routerReplace } from '@/router/navigation';
import { ROUTER_PATHS } from '@/router/constants';
import LImg from '@/components/l-img.vue';
import LButton from '@/components/l-button.vue';

const { t } = useI18n();

// 环境变量
const appTitle = ref(process.env.VITE_APP_TITLE);
const appLogo = ref(process.env.VITE_APP_LOGO);

// Props
const props = defineProps({
    visible: {
        type: Boolean,
        default: false
    }
});

// Emits
const emit = defineEmits(['update:visible', 'login-success', 'close']);

// 表单数据
const formData = ref({
    email: '',
    password: ''
});

// 表单验证错误
const errors = ref({
    email: '',
    password: ''
});

// 状态管理
const isLoading = ref(false);
const showPassword = ref(false);

// 计算属性
const isFormValid = computed(() => {
    return formData.value.email &&
           formData.value.password &&
           !errors.value.email &&
           !errors.value.password;
});

// 邮箱验证
const validateEmail = () => {
    const email = formData.value.email.trim();
    if (!email) {
        errors.value.email = t('emailRequired');
        return false;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
        errors.value.email = t('validEmail');
        return false;
    }

    errors.value.email = '';
    return true;
};

// 密码验证
const validatePassword = () => {
    const password = formData.value.password;
    if (!password) {
        errors.value.password = t('passwordRequired');
        return false;
    }

    if (password.length < 6 || password.length > 20) {
        errors.value.password = t('loginPasswordLength');
        return false;
    }

    errors.value.password = '';
    return true;
};

// 清除邮箱错误
const clearEmailError = () => {
    if (errors.value.email) {
        errors.value.email = '';
    }
};

// 清除密码错误
const clearPasswordError = () => {
    if (errors.value.password) {
        errors.value.password = '';
    }
};

// 切换密码显示
const togglePassword = () => {
    showPassword.value = !showPassword.value;
};

// 点击登录
const clickLogin = async () => {
    if (!validateEmail() || !validatePassword()) {
        return;
    }

    isLoading.value = true;

    try {
        await ApiUser.login(formData.value.email, formData.value.password);
        ElMessage.success(t('loginSuccess'));
        emit('login-success');
        emit('update:visible', false);
    } catch (error) {
        console.error('Login failed:', error);
        ElMessage.error(error.message || t('loginFailed'));
    } finally {
        isLoading.value = false;
    }
};

// 点击忘记密码
const clickForgotPassword = () => {
    emit('update:visible', false);
    routerReplace(ROUTER_PATHS.FORGOT_PASSWORD);
};

// 点击关闭
const clickClose = () => {
    emit('close');
    emit('update:visible', false);
};

// 点击遮罩层
const clickOverlay = () => {
    emit('close');
    emit('update:visible', false);
};

// 监听弹窗显示状态，重置表单
watch(() => props.visible, (newVal) => {
    if (newVal) {
        // 重置表单数据
        formData.value = {
            email: '',
            password: ''
        };
        // 重置错误信息
        errors.value = {
            email: '',
            password: ''
        };
        // 重置状态
        isLoading.value = false;
        showPassword.value = false;
    }
});
</script>

