<script setup>
    import AppNavbar from '@/components/app-navbar.vue';
    import NotFoundView from '@/views/NotFound.vue';
    import LoginExpiredDialog from '@/components/dialog/login-expired-dialog.vue';
    import SearchSidebar from '@/components/search-sidebar.vue';
    import { ref, onMounted, shallowRef, computed, nextTick ,onUnmounted} from 'vue';
    import { useRoute, useRouter } from 'vue-router';
    import { isEnvLocal } from '@/utils/global';
    import { ApiUser } from '@/api/api-user';
    import { routerToLogin } from '@/router/navigation';
    import { useI18n } from 'vue-i18n';
    import { ElMessage } from 'element-plus';
    import { WarnTriangleFilled } from '@element-plus/icons-vue';
    import { useNetworkStatusStore } from '@/store/modules/network-status';
    const { t } = useI18n();
    import { useDeviceDetection } from '@/utils/device-detector';
    import { pxToRem } from '@/utils/px-to-rem';
    const route = useRoute();
    const router = useRouter();
    const { isMobile } = useDeviceDetection();
    const isEnvLocalStatus = ref(false);
    // 使用shallowRef存储动态导入的组件，避免Vue警告
    const StagewiseToolbar = shallowRef(null);

    const mainHeight = ref(pxToRem(window.innerHeight));
    
    // 使用网络状态store
    const networkStatusStore = useNetworkStatusStore();
    
    // 网络状态变化处理函数
    const handleNetworkStatusChange = (isOnline) => {
        if (!isOnline) {
          console.log(isOnline,'isOnline')
            ElMessage.warning({
                message: t('youAreOffline'),
                icon: WarnTriangleFilled
            });
        } else {
            ElMessage.success(t('youAreOnline'));
        }
    };

    // 路由加载状态
    const isNavigating = ref(false);

    // 登录过期弹窗状态
    const loginExpiredDialogVisible = ref(false);

    isEnvLocalStatus.value = isEnvLocal();

    // 改进的404检测 - 考虑路由加载状态
    const isNotFoundPage = computed(() => {
        // 如果路由还没有准备好或正在导航中，不显示404
        if (isNavigating.value) {
            return false;
        }

        // 只有在路由完全准备好且没有匹配时，才显示404
        return route.matched.length === 0;
    });


    // 监听路由变化，管理导航状态
    router.beforeEach((to, from, next) => {
        isNavigating.value = true;
        next();
    });

    router.afterEach((to, from, failure) => {
        // 使用 nextTick 确保组件完全渲染后再设置状态
        nextTick(() => {
            isNavigating.value = false;
        });
    });
    // 处理登录成功
    const onLoginSuccess = () => {
        loginExpiredDialogVisible.value = false;
        // 刷新页面或重新加载用户信息
        window.location.reload();
    };

    // 处理弹窗关闭
    const onDialogClose = () => {
        loginExpiredDialogVisible.value = false;
        // 执行登出操作
        ApiUser.logout();
        // 跳转到登录页面
        routerToLogin();
    };

    // 暴露给全局使用的方法
    window.showLoginExpiredDialog = () => {
        if (window.location.href.includes('login')) return;
        loginExpiredDialogVisible.value = true;
    };
    // 在组件挂载时动态导入stagewise工具栏组件
    onMounted(async () => {
        if (isEnvLocalStatus.value) {
            try {
                const module = await import('./components/stagewise-toolbar.vue');
                StagewiseToolbar.value = module.default;
            } catch (error) {
                console.error('Failed to load StagewiseToolbar:', error);
            }
        }
        
        // 初始化网络状态监听
        networkStatusStore.setNetworkStatusChangeCallback(handleNetworkStatusChange);
        networkStatusStore.initNetworkListener();
    });

    onUnmounted(() => {
        // 清理网络状态监听
        networkStatusStore.removeNetworkListener();
    });

</script>

<template>
    <!-- 404页面：显示empty-page组件 -->
    <div v-if="isNotFoundPage" class="app-container">
        <NotFoundView />
    </div>

    <!-- 正常页面：显示navbar和router-view -->
    <div v-else style="display: flex;">
      <div class="app-container" :style="{height: mainHeight}">
        <app-navbar />
        <div class="app-content">
            <router-view :key="route.name"></router-view>
        </div>
      </div>
      <!-- 搜索侧边栏组件 -->
      <SearchSidebar />
    </div>

    <!-- 登录过期弹窗 -->
    <LoginExpiredDialog
        v-model:visible="loginExpiredDialogVisible"
        @login-success="onLoginSuccess"
        @close="onDialogClose"
    />

    <!-- 只在开发环境中渲染stagewise工具栏 -->
    <component :is="StagewiseToolbar" v-if="isEnvLocalStatus && StagewiseToolbar" />
</template>

