/**
 * 分享相关API服务
 * 提供会话分享等功能
 */
import { ApiClient } from './client-api';
import { ApiResponse } from './definitions';
import {
    API_SESSION_SHARE,
    API_SESSION_SHARED
} from './api-url';
import {
    SessionShareResponseInfo
} from '../models/share-models';
import { SessionResponseInfo } from '../models/chat-models';

/**
 * 分享API服务类
 * 集中管理所有分享相关的API调用
 */
export class ApiShare {
    /**
     * 创建会话分享链接
     * @param id 会话ID
     * @returns 分享响应
     */
    static async createSessionShare(id: number): Promise<ApiResponse<SessionShareResponseInfo>> {
        return await ApiClient.post(
            API_SESSION_SHARE,
            { id },
            SessionShareResponseInfo
        );
    }

    /**
     * 获取分享的会话内容
     * @param share_id 分享ID
     * @param page_size 每页数量
     * @param cursor 游标ID，用于分页（传入上一页最后一条记录的ID）
     * @returns 会话信息
     */
    static async getSharedSession(share_id: string, page_size: number, cursor: number): Promise<ApiResponse<SessionResponseInfo>> {
        // 注意：这个API使用路径参数，需要特殊处理
        const url = `${API_SESSION_SHARED}/${share_id}`;

        return await ApiClient.post(
            url,
            {
                page_size,
                cursor
            },
            SessionResponseInfo
        );
    }
}