              show-password
              class="create-admin-input"
            />
          </el-form-item>
          <el-form-item>
            <div class="checkbox" @click="createForm.is_admin = !createForm.is_admin">
                        <div class="checkbox-inner" :class="{ 'checked': createForm.is_admin }">
                            <l-img v-if="createForm.is_admin" :src="'/static/images/password-show.png'" w="12px" h="12px" />
                            <l-img v-else :src="'/static/images/password-hide.png'" w="14px" h="14px" />
                        </div>
            </div>
            <span class="create-admin-checkbox-text" @click="createForm.is_admin = !createForm.is_admin">{{ $t('canCreateAccounts') }}</span>
          </el-form-item>
        </el-form>
      </div>

        <template #footer>
          <div class="dialog-footer-create-admin">
            <div @click="createDialogVisible = false" class="cancel-btn">{{
              $t('cancel')
            }}</div>
            <el-button
              type="primary"
              @click="submitCreateForm"
              :loading="submitting"
              class="create-admin-btn"
              :class="{ 'disabled': submitting }"
            >
              {{ $t('createAccount') }}
          </el-button>
          </div>
        </template>
      </el-dialog>

      <!-- 账号创建成功对话框 -->
      <el-dialog
        v-model="successDialogVisible"
        :title="$t('adminCreated')"
        :width="pxToRem('480px')"
        :close-on-click-modal="false"
        :show-close="false"
        class="create-admin-dialog"
        append-to-body
      >
        <template #header>
          <div class="create-admin-header">
            <h2 class="admin-list-title">{{ $t('adminCreated') }}</h2>
            <div class="header-actions">
              <l-img
               @click="successDialogVisible = false"
                src="/static/images/close_icon.png"
                w="20px"
                h="20px"

                class="close-btn"
              ></l-img>
            </div>
          </div>
        </template>
        <!-- <el-divider class="confirm-divider"></el-divider> -->
        <div class="success-icon-box">
          <div class="success-icon">
            <l-img
              src="/static/images/checked_icon.png"
              w="24px"
              h="24px"
            ></l-img>
          </div>
        </div>

        <p class="success-message">{{ $t('accountCopied') }}</p>
        <div class="account-info">
          <p class="info-item">
            <span class="info-label">{{ $t('nickname') }}:</span>
            {{ newAdmin.nickname }}
          </p>
          <p class="info-item">
            <span class="info-label">{{ $t('email') }}:</span>
            {{ newAdmin.email }}
          </p>
          <p class="info-item">
            <span class="info-label">{{ $t('password') }}:</span>
            {{ newAdmin.password }}
          </p>
        </div>
        <template #footer>
          <div class="dialog-footer">
            <div type="primary" @click="copyNewAdminInfo" class="reset-password-btn-sure create-admin-copy-btn">
              {{ $t('copy') }}
            </div>
          </div>
