            {{ resetAdmin.nickname }}
          </p>
          <p class="info-item">
            <span class="info-label">{{ $t('email') }}:</span>
            {{ resetAdmin.email }}
          </p>
          <p class="info-item">
            <span class="info-label">{{ $t('password') }}:</span>
            {{ resetAdmin.password }}
          </p>
        </div>
        <template #footer>
          <div class="dialog-footer">
            <div type="primary" @click="copyResetAdminInfo" class="reset-password-btn-sure create-admin-copy-btn">
