<script setup>
import { ref, reactive, computed, onMounted, watch } from "vue";
import { useRouter } from "vue-router";
import { useI18n } from "vue-i18n";
import LImg from "@/components/l-img.vue";
import LTooltip from "@/components/l-tooltip.vue";
import LPagination from "@/components/l-pagination.vue";
import { copy } from "@/utils/util";
import { ApiAdmin } from "@/api/api-admin";
import { convertUtcToLocal } from "@/utils/util";
import { DATE_FORMATS } from "@/types/date.ts";
import { pxToRem } from "@/utils/px-to-rem";

const props = defineProps({
  visible: {
    type: Boolean,
    default: false,
  },
});

const emit = defineEmits(["update:visible"]);

const { t } = useI18n();
const router = useRouter();

// 对话框显示控制
const dialogVisible = ref(false);
const createDialogVisible = ref(false);
const successDialogVisible = ref(false);
const resetConfirmVisible = ref(false);
const resetSuccessVisible = ref(false);
const statusConfirmVisible = ref(false);
const submitting = ref(false);

// 监听props.visible变化
watch(
  () => props.visible,
  (newVal) => {
    dialogVisible.value = newVal;
    if (newVal) {
      fetchAdminList();
    }
  }
);

// 监听dialogVisible变化
watch(
  () => dialogVisible.value,
  (newVal) => {
    emit("update:visible", newVal);
  }
);

// 管理员列表数据
const adminList = ref([]);
const loading = ref(true);
const total = ref(0);
const currentPage = ref(1);
const pageSize = ref(8);

// 表单与数据
const createFormRef = ref(null);
const createForm = reactive({
  nickname: "",
  email: "",
  password: "",
  is_admin: false,
});
const createRules = {
  nickname: [
    { required: true, message: t('nicknameRequired'), trigger: "blur" },
    { min: 2, max: 50, message: t('nicknameLength'), trigger: "blur" },
  ],
  email: [
    { required: true, message: t('emailRequired'), trigger: "blur" },
    { type: "email", message: t('emailInvalid'), trigger: "blur" },
  ],
  password: [
    { required: true, message: t('passwordRequired'), trigger: "blur" },
    { min: 6, max: 20, message: t('passwordLength'), trigger: "blur" },
  ],
};

// 当前操作的管理员
const currentAdmin = ref(null);
const newAdmin = ref({
  nickname: "",
  email: "",
  password: "",
});
const resetAdmin = ref({
  nickname: "",
  email: "",
  password: "",
});

// 状态修改确认信息
const statusConfirmMessage = computed(() => {
  if (!currentAdmin.value) return "";

  return currentAdmin.value.is_active
    ? t('confirmDisableAccount')
    : t('confirmEnableAccount');
});


// 生命周期钩子
onMounted(() => {
  if (props.visible) {
    fetchAdminList();
  }
});

// 获取管理员列表
const fetchAdminList = async () => {
  loading.value = true;
  const params = {
    page_size: pageSize.value,
    page: currentPage.value,
  }
  try {
    const res = await ApiAdmin.getAdminList(params);
    if (res.code === 200) {
      // 确保 res.data 是数组
      if (res.data && Array.isArray(res.data.items)) {
        adminList.value = res.data.items;
        total.value = res.data.total;
      } else {
        console.error(res.data);
        adminList.value = []; // 确保设置为空数组而不是非数组值
        total.value = 0;
      }
    }
  } catch (error) {
    console.error("Failed to fetch admin list:", error);
    // ElMessage.error(t('loadError'));
  } finally {
    loading.value = false;
  }
};

// 分页处理
const handleSizeChange = (size) => {
  pageSize.value = size;
  fetchAdminList();
};

const handleCurrentChange = (page) => {
  currentPage.value = page;
  fetchAdminList();
};

// 关闭页面
const handleClose = () => {
  dialogVisible.value = false;
};

// 显示创建管理员对话框
const showCreateAdminDialog = () => {
  createForm.nickname = "";
  createForm.email = "";
  createForm.password = "";
  createForm.is_admin = false;
  createDialogVisible.value = true;
};

// 提交创建表单
const submitCreateForm = async () => {
  if (!createFormRef.value || submitting.value) return;

  await createFormRef.value.validate(async (valid) => {
    if (valid) {
      submitting.value = true;
      try {
        const res = await ApiAdmin.createAdmin(createForm);
        if (res.code === 200) {
          createDialogVisible.value = false;

          // 设置新管理员信息，从表单中获取而不是从后端返回值中获取
          // 如果后端返回了密码，则使用后端返回的密码
          newAdmin.value = {
            nickname: createForm.nickname,
            email: createForm.email,
            password: res.data && res.data.password ? res.data.password : createForm.password,
          };

          // 显示成功对话框
          successDialogVisible.value = true;

          // 刷新列表
          fetchAdminList();
        } else {
          ElMessage.error(res.message || t('createError'));
        }
      } catch (error) {
        console.error("Create admin error:", error);
        // ElMessage.error(t('createError'));
      } finally {
        submitting.value = false;
      }
    }
  });
};

// 复制新创建的管理员信息
const copyNewAdminInfo = () => {
  const text = `${t('nickname')}: ${
    newAdmin.value.nickname
  }\n${t('email')}: ${newAdmin.value.email}\n${t(
    "password"
  )}: ${newAdmin.value.password}`;
  copyToClipboard(text);
  ElMessage.success(t('accountCopied'));
  successDialogVisible.value = false;
};

// 确认重置密码
const confirmResetPassword = (admin) => {
  currentAdmin.value = admin;
  resetConfirmVisible.value = true;
};

// 重置密码
const resetPassword = async () => {
  if (!currentAdmin.value) return;

  submitting.value = true;
  try {
    const res = await ApiAdmin.resetPassword(currentAdmin.value.id);
    if (res.code === 200 && res.data) {
      resetConfirmVisible.value = false;

      // 设置重置后的管理员信息
      resetAdmin.value = {
        nickname: res.data.nickname || currentAdmin.value.nickname,
        email: res.data.email || currentAdmin.value.email,
        password: res.data.password || '',
      };

      // 显示成功对话框
      resetSuccessVisible.value = true;

      // 刷新列表
      fetchAdminList();
    } else {
      ElMessage.error(res.message || t('resetError'));
    }
  } catch (error) {
    console.error("Reset password error:", error);
    // ElMessage.error(t('resetError'));
  } finally {
    submitting.value = false;
  }
};

// 复制重置后的管理员信息
const copyResetAdminInfo = () => {
  const text = `${t('nickname')}: ${
    resetAdmin.value.nickname
  }\n${t('email')}: ${resetAdmin.value.email}\n${t(
    "password"
  )}: ${resetAdmin.value.password}`;
  copyToClipboard(text);
  ElMessage.success(t('accountCopied'));
  resetSuccessVisible.value = false;
};

// 确认修改状态
const confirmStatusChange = (admin) => {
  currentAdmin.value = admin;
  statusConfirmVisible.value = true;
};

// 修改管理员状态
const changeAdminStatus = async () => {
  if (!currentAdmin.value) return;

  submitting.value = true;
  try {
    let res;
    if (currentAdmin.value.is_active) {
      res = await ApiAdmin.deactivateAdmin(currentAdmin.value.id);
    } else {
      res = await ApiAdmin.activateAdmin(currentAdmin.value.id);
    }

    if (res.code === 200) {
      statusConfirmVisible.value = false;
      ElMessage.success(
        currentAdmin.value.is_active
          ? t('accountDisabled')
          : t('accountEnabled')
      );

      // 刷新列表
      fetchAdminList();
    } else {
      ElMessage.error(res.message || t('statusError'));
    }
  } catch (error) {
    console.error("Change admin status error:", error);
    // ElMessage.error(t('statusError'));
  } finally {
    submitting.value = false;
  }
};

// 复制管理员信息
const copyAdminInfo = (admin) => {
  const text = `${t('nickname')}: ${admin.nickname}\n${t(
    "email"
  )}: ${admin.email}`;
  copyToClipboard(text);
  ElMessage.success(t('accountCopied'));
};

// 复制到剪贴板
const copyToClipboard = (text) => {
  copy(text)
};

</script>

