<template>
  <div class="deepsearch-header">
    <div class="deepsearch-container" :class="{ 'searching': props.isSearching, 'completed': !props.isSearching }">
      <!-- 左侧搜索进度面板 -->
      <div class="search-progress-sidebar">
        <div class="progress-status">
          <div class="status-icon">
            <l-img
              v-if="!props.isSearching"
              src="/static/logo3.png"
              w="16px" h="16px"
            />
            <lottie-vue
            v-else
                    path="/static/thinking.json"
                    :loop="true"
                    :autoplay="true"
                    width="16px"
                    height="16px"
                />
          </div>
          <div class="status-info">
            <div class="status-text">{{ props.isSearching ? t('searching') : t('completed') }}</div>
            <div class="status-time" v-if="searchStartTime">
              <span>{{ searchDuration }}</span>
              <span v-if="!props.isSearching && !isDeepSearchActive"> · {{ sourcesCount }} {{ t('sources') }}</span>
            </div>
          </div>
        </div>

        <div class="search-steps-list">
          <!-- 正常步骤列表 -->
          <div
            v-for="(step, index) in dynamicSearchSteps"
            :key="step.id"
            class="step-item"
            :class="getStepClass(step, index)"
            @click="scrollToSection(step.id)"
          >
            <div class="step-status">
              <el-icon
              :size="18"
               color="#999"
              v-if="step.status === 'completed'"
              ><SuccessFilled /></el-icon>
              <div
                v-else-if="step.status === 'loading'"
                class="step-loading-icon"
              ></div>
              <el-icon
              v-else-if="step.status === 'active'"
              :size="18"
               color="#333"
              ><SuccessFilled /></el-icon>
              <el-icon
              v-else
              :size="18"
               color="#999"
              ><SuccessFilled /></el-icon>
            </div>
            <span class="step-label">
              {{ step.text }}
            </span>
          </div>
        </div>
      </div>

      <!-- 右侧内容展示区域 -->
      <div class="search-content-area" ref="contentAreaRef">
        <!-- 分析功能部分 -->
        <div class="analysis-sections" v-if="analysisSections.length > 0">
          <div
            v-for="(section, sectionIndex) in analysisSections"
            :key="section.id"
            :id="`section-${section.id}`"
            class="analysis-section"
            v-show="sectionIndex <= currentVisibleSection"
          >
            <h3 class="section-heading">{{ section.title }}</h3>
            <div class="section-content">
              <!-- 显示文本内容 -->
              <ul v-if="section.items && section.items.length > 0">
                <li
                  v-for="(item, itemIndex) in section.items"
                  :key="itemIndex"
                  v-show="shouldShowItem(sectionIndex, itemIndex)"
                  v-html="formatItemContent(item)"
                >
                </li>
              </ul>
              <div v-else class="content-paragraph" v-html="formatContent(section.content || '')">
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, nextTick, onMounted, onUnmounted, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from "@/components/l-img.vue";
import LottieVue from '@/components/lottie.vue';

const { t } = useI18n();

// DeepSearch 流式响应常量定义
const DEEP_SEARCH_CONSTANTS = {
  // DeepSearch 状态标记（文本格式）
  STATUS_MARKERS: {
    START: '[DEEPSEARCH_START]',        // DeepSearch 开始标记
    END: '[DEEPSEARCH_END]'            // DeepSearch 结束标记
  },

  // 内容类型标记（文本格式）
  CONTENT_MARKERS: {
    TITLE: '[TITLE]',       // 标题标记
    ITEM: '[ITEM]',         // 列表项标记
    CONTENT: '[CONTENT]'    // 普通内容标记
  },

  // 步骤ID标记
  STEP_MARKER: '[STEP:'    // 步骤标记，格式：[STEP:1]
};

const props = defineProps({
  isSearching: {
    type: Boolean,
    default: false,
  },
  searchSteps: {
    type: Array,
    default: () => []
  },
  searchResults: {
    type: Array,
    default: () => []
  },
  currentStep: {
    type: Number,
    default: 0
  },
  // 新增：流式数据
  streamData: {
    type: [Object, String],
    default: () => null
  }
});

const contentAreaRef = ref(null);
const activeStepId = ref(1); // 当前活跃的步骤ID
const currentVisibleSection = ref(-1); // 当前可见的section索引，初始为-1表示没有显示任何section
const currentVisibleItems = ref({}); // 每个section当前可见的item数量

// 流式数据状态管理
const isDeepSearchActive = ref(false); // DeepSearch 是否激活
const streamSections = ref([]); // 从流式数据构建的sections
const currentStreamSection = ref(null); // 当前正在处理的section

// 搜索统计数据
const searchStartTime = ref(null); // 搜索开始时间
const searchEndTime = ref(null); // 搜索结束时间
const totalSources = ref(0); // 总来源数量
const realTimeTimer = ref(null); // 实时更新定时器

// 格式化缓存，避免重复处理
const formatCache = new Map();

// 自动滚动控制
const isAutoScrollEnabled = ref(true); // 是否启用自动滚动
const isUserScrolling = ref(false); // 用户是否正在手动滚动

// 滚动监听的节流函数
let scrollTimeout = null;

// 强制更新时间显示的响应式变量
const forceUpdateTime = ref(0);

// 检查是否滚动到底部
const isScrolledToBottom = () => {
  if (!contentAreaRef.value) return false;
  const container = contentAreaRef.value;
  const threshold = 10; // 10px的容差
  return container.scrollTop + container.clientHeight >= container.scrollHeight - threshold;
};

// 自动滚动到底部
const scrollToBottom = () => {
  if (!contentAreaRef.value || !isAutoScrollEnabled.value) return;

  nextTick(() => {
    const container = contentAreaRef.value;
    container.scrollTo({
      top: container.scrollHeight,
      behavior: 'smooth'
    });
  });
};

// 处理用户滚动事件
const handleUserScroll = () => {
  if (!contentAreaRef.value) return;

  // 标记用户正在滚动
  isUserScrolling.value = true;

  // 检查是否滚动到底部
  if (isScrolledToBottom()) {
    // 用户滚动到底部，恢复自动滚动
    isAutoScrollEnabled.value = true;
  } else {
    // 用户没有滚动到底部，禁用自动滚动
    isAutoScrollEnabled.value = false;
  }

  // 清除之前的定时器
  if (scrollTimeout) {
    clearTimeout(scrollTimeout);
  }

  // 500ms后重置用户滚动状态
  scrollTimeout = setTimeout(() => {
    isUserScrolling.value = false;
  }, 500);
};

// 监听搜索状态变化
watch(() => props.isSearching, (newVal) => {
  if (newVal) {
    // 搜索开始时重置状态和记录时间
    activeStepId.value = 1;
    currentVisibleSection.value = -1;
    currentVisibleItems.value = {};

    // 如果不是DeepSearch，也记录开始时间
    if (!isDeepSearchActive.value) {
      searchStartTime.value = Date.now();
      searchEndTime.value = null;
      totalSources.value = 0;
    }

    // 启动实时更新定时器
    startRealTimeTimer();
  } else {
    // 搜索结束时记录结束时间
    if (!isDeepSearchActive.value && searchStartTime.value) {
      searchEndTime.value = Date.now();
    }

    // 停止实时更新定时器
    stopRealTimeTimer();
  }
});

// 监听流式数据搜索状态变化
watch(() => isDeepSearchActive.value, (newVal) => {
  if (newVal) {
    // 流式搜索开始时重置状态
    activeStepId.value = 1;
    currentVisibleSection.value = -1;
    currentVisibleItems.value = {};
    streamSections.value = [];
    currentStreamSection.value = null;

    // 启动实时更新定时器
    startRealTimeTimer();
  } else {
    // 停止实时更新定时器
    stopRealTimeTimer();
  }
});

// 监听内容变化，自动滚动到底部
watch([currentVisibleSection, currentVisibleItems], () => {
  if (!props.isSearching && !isUserScrolling.value) {
    // 延迟一点时间确保DOM更新完成
    setTimeout(() => {
      scrollToBottom();
    }, 100);
  }
}, { deep: true });

// 判断是否应该显示某个item
const shouldShowItem = (sectionIndex, itemIndex) => {
  return (currentVisibleItems.value[sectionIndex] || 0) > itemIndex;
};

// 动态生成左侧步骤
const dynamicSearchSteps = computed(() => {
  // 如果有sections，显示所有已创建的sections
  if (streamSections.value.length > 0) {
    return streamSections.value.map((section, index) => {
      const stepId = section.stepId;
      let status = 'pending';

      // 判断状态：
      // - 如果stepId小于activeStepId，标记为completed
      // - 如果stepId等于activeStepId，检查是否有内容来决定是loading还是active
      // - 其他情况标记为pending
      if (stepId < activeStepId.value) {
        status = 'completed';
      } else if (stepId === activeStepId.value) {
        // 检查当前section是否有可见的内容
        const sectionIndex = index;
        const hasVisibleItems = (currentVisibleItems.value[sectionIndex] || 0) > 0;
        const hasContent = section.content && section.content.trim().length > 0;

        // 如果有可见内容，显示active状态，否则显示loading状态
        if (hasVisibleItems || hasContent) {
          status = 'active';
        } else {
          status = 'loading';
        }
      } else {
        status = 'pending';
      }

      return {
        id: stepId,
        text: section.title,
        status: status
      };
    });
  }

  // 如果正在搜索但还没有任何sections，显示初始loading步骤
  if ((props.isSearching || isDeepSearchActive.value)) {
    return [
      { id: 1, text: t('initializing'), status: 'loading' }
    ];
  }

  // 默认返回空数组
  return [];
});

// 监听滚动事件，自动更新活跃步骤
const handleScroll = () => {
  // 处理用户滚动逻辑
  handleUserScroll();

  if (scrollTimeout) {
    clearTimeout(scrollTimeout);
  }

  scrollTimeout = setTimeout(() => {
    if (!contentAreaRef.value || streamSections.value.length === 0) return;

    const container = contentAreaRef.value;
    const containerTop = container.scrollTop;
    const containerHeight = container.clientHeight;
    const containerScrollHeight = container.scrollHeight;

    // 检查是否滚动到顶部（容差10px）
    const isAtTop = containerTop <= 10;

    // 检查是否滚动到底部（容差10px）
    const isAtBottom = containerTop + containerHeight >= containerScrollHeight - 10;

    // 找到当前可见的section
    let currentActiveStepId = 1; // 默认为第一个步骤

    if (isAtTop) {
      // 如果滚动到顶部，选中第一个section
      currentActiveStepId = 1;
    } else if (isAtBottom) {
      // 如果滚动到底部，选中最后一个section
      currentActiveStepId = streamSections.value.length;
    } else {
      // 正常滚动时的逻辑
      let foundActiveSection = false;

      for (let i = 0; i < streamSections.value.length; i++) {
        const section = streamSections.value[i];
        const element = container.querySelector(`#section-${section.id}`);

        if (element) {
          const elementTop = element.offsetTop - container.offsetTop;
          const elementBottom = elementTop + element.offsetHeight;

          // 检查section是否在视窗中可见
          // 如果section的顶部在视窗的上半部分，或者section正在视窗中显示
          if (elementTop <= containerTop + containerHeight / 2 && elementBottom > containerTop) {
            currentActiveStepId = section.stepId;
            foundActiveSection = true;
          }
        }
      }

      // 如果没有找到活跃的section，保持当前选中的步骤
      if (!foundActiveSection) {
        currentActiveStepId = activeStepId.value;
      }
    }

    // 更新activeStepId
    activeStepId.value = currentActiveStepId;

    console.log('🔍 Scroll detected, containerTop:', containerTop, 'isAtTop:', isAtTop, 'isAtBottom:', isAtBottom, 'activeStepId:', currentActiveStepId);
  }, 100);
};

// 组件挂载时添加滚动监听
onMounted(() => {
  if (contentAreaRef.value) {
    contentAreaRef.value.addEventListener('scroll', handleScroll);
  }
});

// 组件卸载时移除滚动监听
onUnmounted(() => {
  if (contentAreaRef.value) {
    contentAreaRef.value.removeEventListener('scroll', handleScroll);
  }
  if (scrollTimeout) {
    clearTimeout(scrollTimeout);
  }

  // 清理实时更新定时器
  stopRealTimeTimer();
});

// 计算属性
const searchQuery = computed(() => {
  // 从流式数据中获取搜索查询，如果没有则返回空
  return '';
});

const searchResults = computed(() => {
  // 使用props传入的搜索结果
  return props.searchResults || [];
});

const analysisSections = computed(() => {
  // 使用流式数据构建的sections
  return streamSections.value;
});

// 方法
const getStepClass = (step, index) => {
  const stepId = step.id || index + 1;
  return {
    'step-completed': step.status === 'completed',
    'step-active': step.status === 'active',
    'step-pending': step.status === 'pending',
    'step-loading': step.status === 'loading'
  };
};

const scrollToSection = (stepId) => {
  if (!contentAreaRef.value) return;

  console.log('🔍 Scrolling to section:', stepId);

  // 立即更新activeStepId，避免延迟导致的状态错误
  activeStepId.value = stepId;

  // 特殊处理第一个步骤
  if (stepId === 1) {
    console.log('🔍 Scrolling to first section (top)');
    // 禁用自动滚动
    isAutoScrollEnabled.value = false;

    // 滚动到顶部
    contentAreaRef.value.scrollTo({
      top: 0,
      behavior: 'smooth'
    });

    // 延迟重新启用滚动检测
    setTimeout(() => {
      isAutoScrollEnabled.value = true;
    }, 1000);
    return;
  }

  // 根据stepId找到对应的section
  const targetSection = streamSections.value.find(section => section.stepId === stepId);
  if (!targetSection) {
    console.log('🔍 Target section not found:', stepId);
    return;
  }

    nextTick(() => {
    const targetElement = contentAreaRef.value.querySelector(`#section-${targetSection.id}`);
    console.log('🔍 Target element:', targetElement, 'ID:', `section-${targetSection.id}`);

      if (targetElement) {
      // 禁用自动滚动，因为这是用户主动操作
      isAutoScrollEnabled.value = false;

        // 计算目标位置，距离顶部留出20px的间距
        const container = contentAreaRef.value;
        let targetTop = targetElement.offsetTop - container.offsetTop - 20;

        // 确保滚动位置不会是负数
        targetTop = Math.max(0, targetTop);

      console.log('🔍 Scrolling to position:', targetTop);

        // 平滑滚动到目标位置
        container.scrollTo({
          top: targetTop,
          behavior: 'smooth'
        });

      // 滚动完成后重新启用滚动检测（1秒后）
      setTimeout(() => {
        // 检查是否滚动到底部，如果是则保持自动滚动禁用
        if (!isScrolledToBottom()) {
          isAutoScrollEnabled.value = false;
      } else {
          isAutoScrollEnabled.value = true;
        }
      }, 1000);
    } else {
      console.log('🔍 Target element not found in DOM');
    }
  });
};

// 处理流式数据
const processStreamData = (data) => {
  console.log('🔍 Processing stream data:', data, 'type:', typeof data);

  if (!data || typeof data !== 'string') return;

  const content = data.trim();
  if (!content) return;

  console.log('🔍 Processing content:', content);

  // 检查DeepSearch状态标记
  if (content === DEEP_SEARCH_CONSTANTS.STATUS_MARKERS.START) {
    console.log('🔍 DeepSearch START detected');
    isDeepSearchActive.value = true;
    streamSections.value = [];
    currentStreamSection.value = null;
    currentVisibleSection.value = -1;
    currentVisibleItems.value = {};
    activeStepId.value = 1;

    // 记录搜索开始时间
    searchStartTime.value = Date.now();
    searchEndTime.value = null;
    totalSources.value = 0;

    return;
  }

  if (content === DEEP_SEARCH_CONSTANTS.STATUS_MARKERS.END) {
    console.log('🔍 DeepSearch END detected');
    isDeepSearchActive.value = false;

    // 记录搜索结束时间
    searchEndTime.value = Date.now();

    return;
  }

  // 检查标题标记
  if (content.startsWith(DEEP_SEARCH_CONSTANTS.CONTENT_MARKERS.TITLE)) {
    console.log('🔍 TITLE detected:', content);
    const titleContent = content.substring(DEEP_SEARCH_CONSTANTS.CONTENT_MARKERS.TITLE.length).trim();

    // 检查是否包含步骤ID
    let stepId = streamSections.value.length + 1;
    let title = titleContent;

    const stepMatch = titleContent.match(/\[STEP:(\d+)\](.+)/);
    if (stepMatch) {
      stepId = parseInt(stepMatch[1]);
      title = stepMatch[2].trim();
    }

    console.log('🔍 Creating new section:', { stepId, title });

    // 创建新的section
    const newSection = {
      id: `stream-section-${stepId}`,
      title: title,
      items: [],
      content: '',
      stepId: stepId
    };

    streamSections.value.push(newSection);
    currentStreamSection.value = newSection;

    // 设置activeStepId为新步骤，这样新步骤会显示为loading状态（因为还没有内容）
    // 同时前面的步骤会被标记为completed
    activeStepId.value = stepId;

    console.log('🔍 Updated streamSections:', streamSections.value);
    console.log('🔍 Set activeStepId to:', stepId);

    // 延迟显示section，让用户先看到loading状态
    setTimeout(() => {
      currentVisibleSection.value = streamSections.value.length - 1;
      console.log('🔍 Made section visible:', currentVisibleSection.value);

      // 触发自动滚动
      scrollToBottom();
    }, 400); // 400ms后显示section标题

    return;
  }

  // 检查列表项标记
  if (content.startsWith(DEEP_SEARCH_CONSTANTS.CONTENT_MARKERS.ITEM)) {
    console.log('🔍 ITEM detected:', content);
    const itemContent = content.substring(DEEP_SEARCH_CONSTANTS.CONTENT_MARKERS.ITEM.length).trim();

    if (currentStreamSection.value && itemContent) {
      currentStreamSection.value.items.push(itemContent);

      // 延迟显示item内容，让标题先显示一段时间
      setTimeout(() => {
        // 立即更新可见items，让新的item可见
        const sectionIndex = streamSections.value.length - 1;
        if (!currentVisibleItems.value[sectionIndex]) {
          currentVisibleItems.value[sectionIndex] = 0;
        }
        currentVisibleItems.value[sectionIndex] = currentStreamSection.value.items.length;

        console.log('🔍 Added item to section:', itemContent);

        // 当第一个item显示时，如果当前步骤是loading状态，保持在当前步骤但变为active
        // 这样用户可以看到loading -> active的状态变化

        // 触发自动滚动
        scrollToBottom();
      }, 1500); // 延迟1500ms显示内容，让loading状态更明显
    }
    return;
  }

  // 检查内容标记
  if (content.startsWith(DEEP_SEARCH_CONSTANTS.CONTENT_MARKERS.CONTENT)) {
    console.log('🔍 CONTENT detected:', content);
    const textContent = content.substring(DEEP_SEARCH_CONSTANTS.CONTENT_MARKERS.CONTENT.length).trim();

    if (currentStreamSection.value && textContent) {
      // 延迟显示内容，让标题先显示一段时间
      setTimeout(() => {
        currentStreamSection.value.content += textContent;

        console.log('🔍 Added content to section:', textContent);

        // 触发自动滚动
        scrollToBottom();
      }, 1500); // 延迟1500ms显示内容，让loading状态更明显
    }
    return;
  }

  // 如果没有特殊标记，且当前有活跃的section，则作为普通内容添加
  if (currentStreamSection.value) {
    console.log('🔍 Adding plain content to current section:', content);

    // 延迟显示内容，让标题先显示一段时间
    setTimeout(() => {
      currentStreamSection.value.content += content + ' ';

      // 触发自动滚动
      scrollToBottom();
    }, 1500); // 延迟1500ms显示内容，让loading状态更明显
  }
};

// 监听流式数据变化
watch(() => props.streamData, (newData) => {
  console.log('🔍 DeepSearch received streamData:', newData);
  if (newData) {
    processStreamData(newData);
  }
}, { deep: true });

// 格式化item内容
const formatItemContent = (item) => {
  if (!item) return '';

  // 检查缓存
  if (formatCache.has(item)) {
    console.log('🔍 Using cached formatted content for:', item);
    return formatCache.get(item);
  }

  console.log('🔍 Formatting item:', item);
  console.log('🔍 Item type:', typeof item);

  // 如果内容已经包含HTML标签，直接返回，避免重复格式化
  if (item.includes('<a ') || item.includes('<code') || item.includes('<strong') || item.includes('<em')) {
    console.log('🔍 Content already formatted, returning as-is');
    formatCache.set(item, item);
    return item;
  }

  // 处理链接格式：先处理Markdown格式的链接，再处理其他格式
  let formatted = item
    // 1. 先处理Markdown格式的链接 [文本](URL)
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" class="item-link">$1</a>')
    // 2. 处理代码片段 `code`
    .replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>')
    // 3. 处理粗体 **text**
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    // 4. 处理斜体 *text*
    .replace(/\*([^*]+)\*/g, '<em>$1</em>');

  // 5. 最后处理直接的URL，但要避免处理已经在HTML标签中的URL
  // 使用更安全的正则表达式，避免匹配HTML属性中的URL
  formatted = formatted.replace(/(^|[^"'=\s])\s*(https?:\/\/[^\s<>"']+)/g, '$1 <a href="$2" target="_blank" rel="noopener noreferrer" class="item-link">$2</a>');

  console.log('🔍 Original item:', item);
  console.log('🔍 Formatted result:', formatted);
  console.log('🔍 Contains HTML tags:', formatted.includes('<a'));

  // 缓存结果
  formatCache.set(item, formatted);

  return formatted;
};

// 格式化内容
const formatContent = (content) => {
  if (!content) return '';

  // 如果内容已经包含HTML标签，直接返回，避免重复格式化
  if (content.includes('<a ') || content.includes('<code') || content.includes('<strong') || content.includes('<em')) {
    console.log('🔍 Content already formatted, returning as-is');
    return content;
  }

  // 处理段落内容的格式化
  let formatted = content
    // 处理Markdown格式的链接 [文本](URL)
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" class="content-link">$1</a>')
    // 处理直接的URL
    .replace(/(https?:\/\/[^\s]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer" class="content-link">$1</a>')
    // 处理代码片段 `code`
    .replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>')
    // 处理粗体 **text**
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    // 处理斜体 *text*
    .replace(/\*([^*]+)\*/g, '<em>$1</em>')
    // 处理换行
    .replace(/\n/g, '<br>');

  return formatted;
};

// 计算搜索时长
const searchDuration = computed(() => {
  // 使用forceUpdateTime来强制重新计算
  forceUpdateTime.value;

  if (!searchStartTime.value) return '0s';

  const endTime = searchEndTime.value || Date.now();
  const duration = Math.floor((endTime - searchStartTime.value) / 1000);

  if (duration < 60) {
    return `${duration}s`;
  } else {
    const minutes = Math.floor(duration / 60);
    const seconds = duration % 60;
    return `${minutes}m ${seconds}s`;
  }
});

// 启动实时更新定时器
const startRealTimeTimer = () => {
  if (realTimeTimer.value) {
    clearInterval(realTimeTimer.value);
  }

  realTimeTimer.value = setInterval(() => {
    if (searchStartTime.value && !searchEndTime.value) {
      // 强制更新时间显示
      forceUpdateTime.value = Date.now();
    }
  }, 1000); // 每秒更新一次
};

// 停止实时更新定时器
const stopRealTimeTimer = () => {
  if (realTimeTimer.value) {
    clearInterval(realTimeTimer.value);
    realTimeTimer.value = null;
  }
};

// 计算总来源数量
const sourcesCount = computed(() => {
  // 统计所有sections中实际可见的items数量作为来源数量
  return streamSections.value.reduce((total, section, sectionIndex) => {
    const visibleItemsCount = currentVisibleItems.value[sectionIndex] || 0;
    return total + visibleItemsCount;
  }, 0);
});
</script>

