export const MSG_ROLE_USER = 'user'
export const MSG_ROLE_ASSISTANT = 'assistant'

// 消息状态常量
export const MESSAGE_STATUS = {
  SENDING: 'sending',
  SUCCESS: 'success',
  FAILED: 'failed'
};

export const PLACEMENT = {
  START: "start",
  END: "end",
};

export const onSendParseMsg = (res) => {
  let content = res?.content || ''
  if(content.includes('\\n')){
    content = content.replace(/\\n/g, '\n')
  }
  if(content.includes('\\r')){
    content = content.replace(/\\r/g, '\r')
  }
  return {
    id: res?.id || new Date().getTime()*1000,
    content: content,
    role: MSG_ROLE_USER,
    showLoading: false,
    noStyle: true,
    placement: PLACEMENT.END,
    isMarkdown: false,
    maxWidth: '100%',
    ...res
  }
}

export const onAIParseMsg = (res,showLoading = true,isMarkdown = true) => {
  let content = res?.content || ''
  if(content.includes('\\n')){
    content = content.replace(/\\n/g, '\n')
  }
  if(content.includes('\\r')){
    content = content.replace(/\\r/g, '\r')
  }
  return {
    id: res?.id || 0,
    content: content,
    role: MSG_ROLE_ASSISTANT,
    showLoading: showLoading,
    noStyle: true,
    placement: PLACEMENT.START,
    isMarkdown: isMarkdown,
    typing:showLoading ? { step: 6, interval: 50 } : false,
    maxWidth:'100%',
    hasThinking: !!res?.reasoning_content,
    reasoning_content: res?.reasoning_content || '',
    thinking_status: res?.thinking_status || 'end',
    // 新增字段
    messageStatus: MESSAGE_STATUS.SENDING,
    originalParams: null,
      ...res,
  }
}