<template>
  <div class="copy-button-container">
    <l-img
      v-if="copyShow"
      @click="clickCopy"
      src="/static/images/copy_icon.png"
      w="16px"
      h="16px"
      :style="{ cursor: 'pointer' }"
    />
    <el-icon
      v-else
      :size="pxToRem('16px')"
      color="#6B7280"
    >
      <Select />
    </el-icon>
  </div>
</template>

<script setup>
import { ref } from 'vue';
import { Select } from '@element-plus/icons-vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
import LImg from '@/components/l-img.vue';
import { pxToRem } from '@/utils/px-to-rem';
import { copy } from '@/utils/util.js';

const { t } = useI18n();

// 组件props
const props = defineProps({
  // 要复制的文本内容
  content: {
    type: String,
    required: true
  },
  // 复制成功后的提示文本（可选）
  successMessage: {
    type: String,
    default: ''
  },
  // 复制失败后的提示文本（可选）
  errorMessage: {
    type: String,
    default: ''
  },
  // 图标大小
  iconSize: {
    type: String,
    default: pxToRem('16px')
  },
  // 是否显示提示消息
  showMessage: {
    type: Boolean,
    default: true
  }
});

// 组件事件
const emit = defineEmits(['onCopySuccess', 'onCopyError']);

// 复制状态
const copyShow = ref(true);

// 复制功能
const clickCopy = async () => {
  if (!props.content) {
    const errorMsg = props.errorMessage || t('copyFailed');
    if (props.showMessage) {
      ElMessage.error(errorMsg);
    }
    emit('onCopyError', errorMsg);
    return;
  }

  try {
    copy(props.content);

    // 显示复制成功状态
    copyShow.value = false;

    // 显示成功消息
    const successMsg = props.successMessage || t('copySuccess');
    if (props.showMessage) {
      ElMessage.success(successMsg);
    }
    emit('onCopySuccess', successMsg);

    // 2秒后恢复复制图标
    setTimeout(() => {
      copyShow.value = true;
    }, 2000);

  } catch (error) {
    console.error('Failed to copy text:', error);
    const errorMsg = props.errorMessage || t('copyFailed');
    if (props.showMessage) {
      ElMessage.error(errorMsg);
    }
    emit('onCopyError', errorMsg);
  }
};
</script>

<style scoped>
.copy-button-container {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
</style>