<template>
  <div v-if="visible && isOnChatPage" class="search-sidebar">
    <!-- 头部区域 -->
    <div class="search-sidebar-header">
      <h3>{{ t('searchResults') }}</h3>
      <button @click="closeSidebar" class="close-btn" :title="t('close')">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
          <path d="M15 5L5 15M5 5l10 10" stroke="currentColor" stroke-width="1.67" stroke-linecap="round"/>
        </svg>
      </button>
    </div>
    
    <!-- 内容区域 -->
    <div class="search-sidebar-content" ref="contentRef">
      <div v-if="citations.length === 0" class="empty-state">
        <p>{{ t('noSearchReferences') }}</p>
      </div>
      <div v-else class="citations-container">
        <!-- 常规引用链接 -->
        <div class="regular-citations">
          <div @click="handleCitationClick(citation)" v-for="(citation, index) in citations" :key="index" class="citation-link-card">
            <div class="citation-favicon-container">
              <div class="favicon-border">
                <l-img
                  :src="getFaviconUrl(citation, index)"
                  w='18px'
                  h='18px'
                  radius='6px'
                  class="favicon-icon"
                  @error="handleFaviconError(index)"
                />
              </div>
            </div>
            <div class="citation-text-content">
              <div class="citation-domain-link">
                {{ getDomain(citation) }}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted, nextTick, computed, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRoute } from 'vue-router';
import LImg from '@/components/l-img.vue';
// 引入网站图标工具函数
import { FaviconManager, getDomainFromUrl } from '@/utils/util.js';
// 引入路由常量
import { ROUTER_PATHS } from '@/router/constants.js';

const { t } = useI18n();
const route = useRoute();

// 组件状态
const visible = ref(false);
const citations = ref([]);
const contentRef = ref(null);

// 网站图标管理器
const faviconManager = new FaviconManager();

// 事件处理
const emit = defineEmits(['close']);

// 判断是否在聊天页面
const isOnChatPage = computed(() => {
  return route.path.startsWith(ROUTER_PATHS.ALIEN_CHAT);
});

// 监听路由变化，当离开聊天页面时自动关闭侧边栏
watch(isOnChatPage, (newValue) => {
  if (!newValue && visible.value) {
    // 当离开聊天页面且侧边栏是打开状态时，自动关闭
    closeSidebar();
  }
});

// 关闭侧边栏
const closeSidebar = () => {
  visible.value = false;
  citations.value = [];
  faviconManager.reset(); // 重置图标管理器状态
  emit('close');
};

// 获取网站图标URL
const getFaviconUrl = (url, index) => {
  return faviconManager.getFaviconUrl(url, index);
};

// 处理图标加载失败
const handleFaviconError = (index) => {
  const url = citations.value[index];
  if (url) {
    faviconManager.handleFaviconError(index, url);
  }
};

// 获取域名
const getDomain = (url) => {
  return getDomainFromUrl(url);
};

// 处理搜索侧边栏切换事件
const handleToggleSearchSidebar = (event) => {
  const { citations: newCitations, show } = event.detail;
  citations.value = newCitations || [];
  visible.value = show;
  
  if (show) {
    // 侧边栏打开时，重置图标管理器
    faviconManager.reset();
  }
  
  console.log('Toggle search sidebar:', show, newCitations);
};

// 处理引用链接点击事件
const handleCitationClick = (citation) => {
  window.open(citation, '_blank');
};

// 生命周期
onMounted(() => {
  // 监听搜索侧边栏切换事件
  window.addEventListener('toggleSearchSidebar', handleToggleSearchSidebar);
});

onUnmounted(() => {
  // 清理事件监听器
  window.removeEventListener('toggleSearchSidebar', handleToggleSearchSidebar);
});

// 暴露方法给父组件
defineExpose({
  closeSidebar,
  visible,
  citations
});
</script>

