<script setup>
import { computed, ref, onMounted, onUnmounted ,watch, onBeforeUnmount} from 'vue';
import { useRouter, useRoute } from 'vue-router';
import {ROUTER_PATHS} from '@/router/constants';
import { useUserStore } from '@/store/modules/user';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import { pxToRem } from '@/utils/px-to-rem';
import ConversationView from '@/components/conversation/conversation-history.vue';
import AdminList from './dialog/admin-list.vue';
import Setting from './dialog/setting.vue';
import LTooltip from './l-tooltip.vue';
import { ApiShare } from '@/api/api-share';
import { ElMessage } from 'element-plus';
import { copy } from '@/utils/util';
import { ApiUser } from '@/api/api-user';
import { getAccessToken } from '@/utils/auth';
import {  useDeviceDetection } from '@/utils/device-detector';


// 获取应用标题
const appTitle = ref(import.meta.env.VITE_APP_TITLE);
const appLogo = ref(import.meta.env.VITE_APP_LOGO);
const isConversationDialogVisible = ref(false);
const isAdminListDialogVisible = ref(false);
const isSettingDialogVisible = ref(false);
// 跟踪搜索侧边栏状态
const isSearchSidebarVisible = ref(false);
const isShowLoginBtn = ref(false);

// 国际化
const { t } = useI18n();

const { isMobile } = useDeviceDetection();

// 路由
const router = useRouter();
const route = useRoute();

// 用户状态
const userStore = useUserStore();
const isLoggedIn = computed(() => userStore.isLoggedIn);
const isAdmin = computed(() => userStore.isAdmin);
const userAvatar = computed(() => userStore.currentUser?.displayAvatar);

// 页面状态
const isHomePage = computed(() => route.path === ROUTER_PATHS.HOME);
const isAlienChatPage = computed(() => route.path.startsWith(ROUTER_PATHS.ALIEN_CHAT));
const isSharePage = computed(() => route.path.startsWith(ROUTER_PATHS.SHARE));

// 按钮显示逻辑
const shouldShowNewChatButton = computed(() => isLoggedIn.value && isAlienChatPage.value);
const shouldShowShareButton = computed(() => isLoggedIn.value && isAlienChatPage.value);
const shouldShowHistoryButton = computed(() => isHomePage.value || isAlienChatPage.value || isSharePage.value);

// 计算navbar样式
const navbarStyle = computed(() => {
    // 在小屏幕下始终使用relative定位
    if (windowWidth.value < 1200) {
        return { position: 'relative', zIndex: 3};
    }
});

const isSmallNavbar = computed(() => {
    return route?.meta?.isSmallNavbar;
});

// 是否是横向的整体布局。当是聊天时并且宽度大于1200时，使用两侧布局
const isHorizontalLayout = computed(() => {
  if(isAlienChatPage.value || isSharePage.value){
    // 计算可用宽度：窗口宽度 - 搜索侧边栏宽度（如果打开）
    let availableWidth = windowWidth.value // 减去聊天侧边栏宽度
    if (isSearchSidebarVisible.value) {
      availableWidth -= 600; // 减去搜索侧边栏宽度（使用CSS变量中定义的500px）
    }
    return availableWidth < 1200;
  }
  return true;
});

// 事件处理
const clickNewChat = () => {
    // 处理新建聊天
    router.push(ROUTER_PATHS.HOME);
    window.dispatchEvent(new CustomEvent('toggleSearchSidebar', {
          detail: {
              citations: [],
              show: false
          }
    }));
};

const clickShare = async () => {
    try {
        const sessionId = route.params.sessionId;
        console.log('sessionId', sessionId);

        if (!sessionId) {
            return;
        }

        const response = await ApiShare.createSessionShare(parseInt(sessionId));

        if (response.code === 200) {
            const shareUrl = `${window.location.origin}${ROUTER_PATHS.SHARE}/${response.data.share_id}`;

            copy(shareUrl);
            ElMessage.success(t('shareSuccessTip'));
        } else {
            throw new Error(response.message);
        }
    } catch (error) {
        console.error('Share failed:', error);
        ElMessage.error(t('shareFailedTip'));
    }
};

const clickHistory = () => {
    // 处理历史记录
    console.log('History clicked');
    isConversationDialogVisible.value = true;
};

const clickLogin = () => {
    // 跳转到登录页
    router.push('/login');
};

// 下拉菜单命令处理
const handleDropdownCommand = (command) => {
    if (command === 'settings') {
        // 控制设置组件显示
        isSettingDialogVisible.value = true;
    } else if (command === 'characters') {
        // 跳转到角色列表页面
        router.push(ROUTER_PATHS.CREATE_CHARACTER);
    } else if (command === 'adminList') {
        // 控制管理员列表组件显示
        isAdminListDialogVisible.value = true;
    } else if (command === 'logout') {
        ApiUser.logout();
        router.replace(ROUTER_PATHS.LOGIN);
        window.dispatchEvent(new CustomEvent('toggleSearchSidebar', {
          detail: {
              citations: [],
              show: false
          }
      }));
    } else if (command === 'generatedImages') {
        router.push(ROUTER_PATHS.GENERATED_IMAGES);
    } else if (command === 'generatedVideos') {
        router.push(ROUTER_PATHS.GENERATED_VIDEOS);
    } else if (command === 'myFavorites') {
        router.push(ROUTER_PATHS.MY_FAVORITES);
    }
};

const goHome = () => {
    router.push(ROUTER_PATHS.HOME);
};

// 跟踪窗口宽度
const windowWidth = ref(window.innerWidth);

// 监听窗口大小变化
const handleResize = () => {
    windowWidth.value = window.innerWidth;
};

// 监听搜索侧边栏状态变化
const handleSearchSidebarToggle = (event) => {
    isSearchSidebarVisible.value = event.detail.show;
};

// 跨Tab页登录状态同步 - 简化版本
const handleStorageChange = async (event) => {
    // 只处理localStorage的变化
    if (event.storageArea !== localStorage) return;

    const { key, newValue, oldValue } = event;

    // 监听token变化
    if (key === 'al_ACCESS_TOKEN') {
        if (!newValue && oldValue) {
            // 登出：清除用户信息
            userStore.clearUserInfo();
            console.log('Synced logout from another tab');
        } else if (newValue && !oldValue) {
            // 登录：获取用户信息
            await syncUserInfo();
            console.log('Synced login from another tab');
        }
    }

    // 监听用户信息变化
    if (key === 'user-store') {
        try {
            const userData = newValue ? JSON.parse(newValue) : null;
            if (userData?.userInfo && getAccessToken()) {
                userStore.setUserInfo(userData.userInfo);
                console.log('Synced user info from another tab');
            }
        } catch (error) {
            console.error('Error syncing user info:', error);
        }
    }
};

// 同步用户信息
const syncUserInfo = async () => {
    try {
        const token = getAccessToken();
        if (token && !userStore.isLoggedIn) {
            const userInfo = await ApiUser.getUserAccountInfo();
            if (userInfo?.code === 200) {
                userStore.setUserInfo(userInfo.data);
            }
        }
    } catch (error) {
        console.error('Failed to sync user info:', error);
    }
};

// 初始化登录状态检查
const initLoginSync = async () => {
    const token = getAccessToken();
    const hasUserInfo = userStore.isLoggedIn;

    if (token && !hasUserInfo) {
        await syncUserInfo();
    } else if (!token && hasUserInfo) {
        userStore.clearUserInfo();
    }
};

watch(route, () => {
    isShowLoginBtn.value = route.path !== ROUTER_PATHS.LOGIN;
});

onBeforeUnmount(() => {
    isShowLoginBtn.value = !!route.path && (route.path !== ROUTER_PATHS.LOGIN);
});

onMounted(async () => {
    window.addEventListener('resize', handleResize);
    window.addEventListener('toggleSearchSidebar', handleSearchSidebarToggle);
    // 添加storage事件监听，实现跨Tab页同步
    window.addEventListener('storage', handleStorageChange);
    // 初始化登录状态同步
    await initLoginSync();
});

onUnmounted(() => {
    window.removeEventListener('resize', handleResize);
    window.removeEventListener('toggleSearchSidebar', handleSearchSidebarToggle);
    // 移除storage事件监听
    window.removeEventListener('storage', handleStorageChange);
    console.log('Cross-tab login sync cleanup');
});

</script>

