<template>

  <div class="msg-think-container-header">
    <div v-if="thinkingProcess && thinkReplicate " class="msg-copy-icon">
      <copy-button 
        :content="thinkingOfContent"
        icon-size="16px"
        @onCopySuccess="onCopySuccess"
        @onCopyError="onCopyError"
      />
    </div>
    <div class="msg-think-container">
      <Thinking :modelValue="thinkReplicate" button-width="100%" :status="currentStatus" max-width="100%"
        :content="content" @change="handleChange">
        <template #status-icon>
          <l-img v-if="currentStatus == 'start'" src="/static/images/msg-loading2.png" w="20px" h="20px"></l-img>
          <l-img v-else-if="currentStatus == 'end'" src="/static/images/conversation/think_icon.png" w="16px" h="16px"></l-img>
        </template>
        <template #label>
          <span class="label-text">{{ currentStatus == 'start' ? t('thinking') : t('thinkingFor') }}</span>
        </template>
        <template #content="{ content }">
          <div class="content-container">
            <Typewriter :content="content" :is-markdown="true" :typing="shouldUseTypewriter" :isFog="false" />
          </div>
        </template>

        <template #arrow>
          <el-icon v-if="thinkReplicate" size="12px" color="#6B7280"> <ArrowDownBold /> </el-icon>
          <el-icon v-else size="12px" color="#6B7280"><ArrowDownBold /></el-icon>
        </template>
      </Thinking>

      <!-- 雾化效果区域 - 用于流式响应时的实时显示 -->
      <div class="think-replicate" :style="{
        display: !thinkReplicate && shouldShowReplicate && currentStatus == 'thinking' ? 'block' : 'none',
      }">
        <div class="think-replicate-content">
          <Typewriter :content="streamingContent || content" :is-markdown="true" :typing="isStreaming" :isFog="true" />
        </div>
      </div>
    </div>
  </div>
</template>
<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from "vue";
import { Thinking ,Typewriter} from 'vue-element-plus-x'
import LImg from '@/components/l-img.vue';
import LottieVue from '@/components/lottie.vue';
import CopyButton from '@/components/business/components/copy-button.vue';
import "vue-element-plus-x/styles/prism.min.css";
import { useI18n } from 'vue-i18n';

const { t } = useI18n();

const props = defineProps({
  thinkingProcess: {
    type: String,
    default: ''
  },
  thinkingOfContent: {
    type: String,
    default: ''
  },
  // 新增：思考状态控制 - 为流式响应预留
  status: {
    type: String,
    default: 'end', // 默认为end状态，因为当前是非流式响应
    validator: (value) => ['start', 'thinking', 'end', 'error'].includes(value)
  },
  // 新增：是否为流式响应模式 - 为后续功能预留
  isStreaming: {
    type: Boolean,
    default: false
  },
  // 新增：流式响应的实时内容 - 为后续功能预留
  streamingContent: {
    type: String,
    default: ''
  },
});

const emit = defineEmits(['statusChange', 'toggleExpand']);

// 响应式状态
const thinkReplicate = ref(false);
const currentStatus = ref(props.status);

// 计算属性
const content = computed(() => {
  if (props.thinkingProcess) {
    return props.thinkingProcess;
  }
  return '';
});

// 是否显示雾化区域 - 保持原有逻辑，为流式响应预留
const shouldShowReplicate = computed(() => {
  // 当前非流式响应，保持原有的start状态显示逻辑
  // 为后续流式响应预留thinking状态的显示逻辑
  return currentStatus.value === 'start' || (currentStatus.value === 'thinking' && props.isStreaming);
});

// 是否使用打字机效果 - 当前保持false，为后续功能预留
const shouldUseTypewriter = computed(() => {
  return false; // 当前非流式响应，保持原有的false设置
});

// 复制成功事件处理
const onCopySuccess = (message) => {
  console.log('Copy success:', message);
};

// 复制失败事件处理
const onCopyError = (message) => {
  console.error('Copy error:', message);
};

// 状态变化处理函数
const handleStatusChange = (status) => {
  switch (status) {
    case 'start':
      // 开始思考状态
      thinkReplicate.value = false;
      break;
    case 'thinking':
      // 思考中状态 - 为流式响应预留
      if (props.isStreaming) {
        thinkReplicate.value = false; // 显示雾化区域
      }
      break;
    case 'end':
      // 思考完成状态
      thinkReplicate.value = false; // 可以展开查看完整内容
      break;
    case 'error':
      // 错误状态
      thinkReplicate.value = false;
      break;
  }

  // 向父组件发送状态变化事件
  emit('statusChange', {
    status,
    isExpanded: thinkReplicate.value
  });
};

// 监听props变化 - 正确的位置应该在setup顶层
watch(() => props.status, (newStatus) => {
  currentStatus.value = newStatus;
  // 状态变化时的逻辑处理
  handleStatusChange(newStatus);
}, { immediate: true });

// 展开/收起变化处理
const handleChange = (data) => {
  console.log("Thinking component change:", data);
  thinkReplicate.value = data.value;

  // 向父组件发送展开状态变化事件
  emit('toggleExpand', {
    isExpanded: data.value,
    status: currentStatus.value
  });
};

// 流式响应相关方法 - 为后续功能预留
const startStreaming = () => {
  if (currentStatus.value !== 'thinking') {
    currentStatus.value = 'thinking';
  }
};

const stopStreaming = () => {
  if (currentStatus.value === 'thinking') {
    currentStatus.value = 'end';
  }
};

const handleStreamingError = () => {
  currentStatus.value = 'error';
};

// 暴露方法给父组件使用
defineExpose({
  startStreaming,
  stopStreaming,
  handleStreamingError,
  setStatus: (status) => {
    currentStatus.value = status;
  },
  toggleExpand: () => {
    thinkReplicate.value = !thinkReplicate.value;
  }
});

// 生命周期
onMounted(() => {
  // 组件挂载时的初始化逻辑
  console.log('Think component mounted with status:', currentStatus.value);
});

onUnmounted(() => {
  // 组件卸载时的清理逻辑
  console.log('Think component unmounted');
});
</script>
