<template>
    <div class="conversation-sidebar">
        <div class="search-container">
            <div class="search-input">
                <el-icon>
                    <Search />
                </el-icon>
                <input type="text" :placeholder="t('searchConversations')" v-model="searchText"
                    class="expand-icon" />
                <div v-if="searchText.length > 0" @click.stop="clearSearch" class="search-icon">
                    <el-icon>
                        <CircleClose />
                    </el-icon>
                </div>
            </div>
        </div>
        <div class="sidebar-container">
            <div class="conversations-container">
                <div class="conversations-side" :class="{ 'conversations-side-collapsed': !isExpanded }"
                    @scroll="onScroll">
                    <div v-if="conversationGroups.length == 0 && isLoggedIn" class="no-data-content">
                        <span>{{ t('noResultFound') }}</span>
                    </div>
                    <div v-else-if="!isLoggedIn">
                        <div class="no-login-title">{{ t('history') }}</div>
                        <div class="no-login-desc">
                            <div class="no-sign-button" @click="clickSignIn">
                                {{ t('signInToSeeHistory') }}
                            </div>
                        </div>
                    </div>
                    <div v-else>
                        <div v-for="group in conversationGroups" :key="group.type" class="time-section"
                            :class="`section-${group.type}`">
                            <div class="time-label">{{ searchText ? t('history') : group.label }}</div>
                            <div v-for="conversation in group.list" :key="conversation.id" class="conversation-item"
                                :class="{ active: currentConversation?.id === conversation.id, [`item-${group.type}`]: true }"
                                @mouseenter="handleHoverConversation(conversation)"
                                @click="clickSelectConversation(conversation)">
                                <div class="conversation-content">
                                    <div v-if="editingId == conversation.id" class="conversation-title">
                                        <el-input ref="editingInput" v-model="editingTitle" class="edit-title-input"
                                            size="small" @keyup.enter.stop="confirmEdit(conversation)" @click.stop />
                                        <div @click.stop="clearEditTitle" class="edit-cancel-btn">
                                            <el-icon>
                                                <Close />
                                            </el-icon>
                                        </div>
                                        <div @click.stop="confirmEdit(conversation)"
                                            class="edit-confirm-btn">
                                            <el-icon>
                                                <Check />
                                            </el-icon>
                                        </div>
                                    </div>
                                    <div v-else class="conversation-title">
                                        <div class="conversation-title-text">{{ conversation.title }}</div>
                                        <div class="current-tag" v-if="conversation.id == currentConversationId">{{
                                            t('current') }}
                                        </div>
                                    </div>
                                    <div class="conversation-time">{{ conversation.time }}</div>
                                </div>
                                <div v-if="!isEditing" class="action-buttons">
                                    <div class="action-btn" @click.stop="clickGoToConversation(conversation)">
                                        <l-img :src="'/static/images/conversation/share_icon.png'" w="12px" h="12px" />
                                    </div>
                                    <div class="action-btn" @click.stop="clickEditConversation(conversation)">
                                        <l-img :src="'/static/images/conversation/edit_icon.png'" w="12px" h="12px" />
                                    </div>
                                    <div class="action-btn" @click.stop="clickDeleteConversation(conversation)">
                                        <l-img :src="'/static/images/conversation/delete_icon.png'" w="12px" h="12px" />
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div v-if="loading" class="loading-more">{{ t('loading') }}</div>
                        <div v-if="!hasMore && conversations.length > 0" class="no-more">{{ t('noMore') }}</div>
                    </div>
                </div>
                <div v-if="isExpanded" class="main-content">
                    <div class="shadow-top"></div>
                    <div v-loading="isLoading" v-if="msgList.length > 0" class="chat-detail-content">
                        <div ref="msgListRef" class="msg-list" @scroll="handleScroll">
                            <!-- 加载更多提示 -->
                            <div v-if="isLoading" class="loading-more">
                                <div class="loading-spinner"></div>
                                <span>{{ t('loading') }}</span>
                            </div>
                            <div v-for="(item, index) in msgList" :key="item.id"
                                style="display: flex;flex-direction: column;"
                                :style="{ alignItems: item.role === MSG_ROLE_USER ? 'flex-end' : 'flex-start' }">
                                <div :style="{ marginBottom: getMessageMargin(item, index) }">
                                    <msg-item-text :content="item.content" :role="item.role"
                                        :isMarkdown="item.isMarkdown" :typing="item.typing"
                                        :showLoading="item.showLoading" :hasThinking="item.hasThinking"
                                        :thinkingProcess="item.reasoning_content" :isRecordList="true" />
                                </div>
                            </div>
                            <div ref="lastMsgRef" class="last-msg-ref-small"></div>
                        </div>
                    </div>
                    <div v-if="msgList.length == 0" class="placeholder-content">
                        <h2>{{ t('dialogSelectOrStartNew') }}</h2>
                        <p>{{ t('dialogConversationInfo') }}</p>
                    </div>
                    <div class="shadow-bottom"></div>
                </div>
            </div>
        </div>
        <div class="action-footer">
            <div class="expand-button" @click="clickToggleExpand">
                <l-img :src="'/static/images/conversation/expand_icon.png'" w="16px" h="16px"
                    :style="!isExpanded ? 'transform: rotate(180deg);' : ''" />
                <span>{{ isExpanded ? t('collapse') : t('expand') }}</span>
            </div>
            <div v-if="currentConversation?.id && isLoggedIn" class="action-buttons-container">
                <div class="action-button" @click="clickGoToConversation(currentConversation)">
                    <l-img :src="'/static/images/conversation/go_icon.png'" w="16px" h="16px" />
                    <span>{{ t('go') }}</span>
                </div>
                <div class="action-button" @click="clickEditConversation(currentConversation)">
                    <l-img :src="'/static/images/conversation/edit_button_icon.png'" w="16px" h="16px" />
                    <span>{{ t('edit') }}</span>
                </div>
                <div class="action-button" @click="clickDeleteConversation(currentConversation)">
                    <l-img :src="'/static/images/conversation/delete_button_icon.png'" w="16px" h="16px" />
                    <span>{{ t('delete') }}</span>
                </div>
            </div>
            <div v-if="!isLoggedIn">
                <div class="no-sign-action-button" @click="clickSignIn">
                    <l-img :src="'/static/images/conversation/go_icon.png'" w="16px" h="16px" />
                    {{ t('signIn') }}
                </div>
            </div>
        </div>
        <el-dialog v-model="deleteDialogVisible" width="25%" :show-close="false" class="def-delete-dialog">
            <template #header>
                <div class="def-title-text">{{ t('confirmDeletion') }}</div>
            </template>
            <div class="def-delete-content">
                <div class="def-line def-line-spacer"></div>
                <div class="content-padding">{{ t('deleteChatMessage') }}</div>
            </div>
            <template #footer>
                <div class="dialog-footer">
                    <el-button @click="deleteDialogVisible = false"
                        class="dialog-button">{{ t('cancel') }}</el-button>
                    <el-button color="#DF2D29" @click="confirmDelete"
                        class="dialog-button">{{ t('confirm') }}</el-button>
                </div>
            </template>
        </el-dialog>
    </div>
</template>

<script setup>
import LImg from '@/components/l-img.vue';
import MsgItemText from '@/views/alien/components/msg-item-text.vue';
import { ApiChat } from '@/api/api-chat';

import { ref, computed, onMounted, nextTick, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import {ROUTER_PATHS} from '@/router/constants';
import { routerTo, routerToLogin, routerReplace } from '@/router/navigation';
import { MSG_ROLE_USER } from '@/types/msg.ts';
import { useSmoothScroll, formatRelativeTimeFromUtc, isWithinDaysFromUtc } from '@/utils/util';
import { useConversationStore } from '@/store/modules/conversation';
import { useUserStore } from '@/store/modules/user';
import { onSendParseMsg, onAIParseMsg } from '@/types/msg.ts';
import { pxToRem } from '@/utils/px-to-rem';

const { t } = useI18n();
const { smoothScrollToRef } = useSmoothScroll();
const conversationStore = useConversationStore();
const userStore = useUserStore();
const isLoggedIn = userStore.isLoggedIn;
const currentConversationId = conversationStore.getCurrentConversationId;

const PAGE_SIZE = 20;
const lastId = ref(0);
const hasMore = ref(true);
const msgHasMore = ref(true);
const loading = ref(false);
const conversations = ref([]);
const currentConversation = ref(null);
const isEditing = ref(false);
const isLoading = ref(false);
const msgList = ref([]);
const lastMsgRef = ref(null);
const msgListRef = ref(null);
const isFirstLoad = ref(true);
const lastMsgId = ref(0);
const msgPageSize = ref(20);
const lastScrollTop = ref(0);

const clickSignIn = () => {
    emit('onUpdateVisible', false);
    routerToLogin();
}

// 事件处理
const clickSelectConversation = (conversation) => {
    setCurrentConversationStatus(conversation);
    loadMessages(true);
    routerTo(`/chat/${conversation.id}`, {});
    emit('onUpdateVisible', false);
};

const clickEditConversation = (conversation) => {
    isEditing.value = true;
    editingId.value = conversation.id;
    editingTitle.value = conversation.title;
    nextTick(() => {
        if (editingInput.value) {
            editingInput.value[0].focus();
        }
    });
};

const clickDeleteConversation = (conversation) => {
    conversationToDelete.value = conversation;
    deleteDialogVisible.value = true;
};

const clickGoToConversation = (conversation) => {
    if (conversation.id) {
        setCurrentConversationStatus(conversation);
        window.open(`/chat/${conversation.id}`, '_blank');
    }
};

const onScroll = (e) => {
    const el = e.target;
    if (el.scrollTop + el.clientHeight >= el.scrollHeight - 40 && hasMore.value) {
        loadData(false);
    }
};


const onScrollMsgBottom = async () => {
    await nextTick();
    smoothScrollToRef(lastMsgRef, {
        container: msgListRef.value,
        duration: 1200,
        offset: 20,
        easing: 'easeOutExpo'
    })
}

const setCurrentConversationStatus = (conversation) => {
    currentConversation.value = conversation;
    conversationStore.setCurrentConversationId(conversation.id);
}

// 计算消息间距
const getMessageMargin = (currentItem, index) => {
    // 默认间距
    const defaultMargin = '5px';
    // 相同角色间的间距
    const sameRoleMargin = '20px';

    // 如果是最后一条消息，使用默认间距
    if (index === msgList.value.length - 1) {
        return pxToRem(defaultMargin);
    }

    // 获取下一条消息
    const nextItem = msgList.value[index + 1];

    // 如果当前消息和下一条消息角色相同，使用较大间距
    if (currentItem.role === nextItem.role) {
        return pxToRem(sameRoleMargin);
    }

    // 如果角色不同，使用默认间距
    return pxToRem(defaultMargin);
};

const loadData = async (reset = false) => {
    if (loading.value || (!hasMore.value && !reset)) return;
    loading.value = true;
    try {
        if (reset) {
            lastId.value = 0;
        }
        const res = await ApiChat.getChatHistory(PAGE_SIZE, lastId.value);
        let list = res.data.items || [];
        // 判断是否请求过会话历史接口，如果请求过，则不覆盖原有数据
        const shouldOverride = reset || !conversationStore.hasLoadedHistory;

        if (shouldOverride) {
            // 首次加载、重置或强制重新加载时，覆盖原有数据
            conversations.value = list;
            conversationStore.setConversations(conversations.value);
            conversationStore.setHasLoadedHistory(true);
        } else {
            conversations.value = [...conversations.value, ...list];
            conversationStore.appendConversations(list);
        }
        hasMore.value = res.data.has_more;
        if (list && Array.isArray(list) && list.length > 0) {
            lastId.value = list[list.length - 1].id;
        }
        conversationStore.setPageInfo(lastId.value, hasMore.value);
    } catch{
        hasMore.value = false
    } finally {
        loading.value = false;
        let currentConversation = conversationStore.currentConversation;
        if (currentConversation) {
            setCurrentConversationStatus(currentConversation);
        }
    }
};

const handleScroll = (e) => {
    const el = e.target;
    const currentScrollTop = el.scrollTop;

    // 计算滚动方向
    const isScrollingUp = currentScrollTop < lastScrollTop.value;

    // 增加更大的触发阈值，使检测更加灵敏
    const SCROLL_THRESHOLD = 50; // 增加阈值到50px

    // 检查是否向上滚动(当前滚动位置小于上次位置)且接近顶部
    if (isScrollingUp && currentScrollTop <= SCROLL_THRESHOLD && !isLoading.value && msgHasMore.value) {
        console.log('触发加载更多消息');
        loadMessages(false);
    }

    // 更新上次滚动位置，但仅在非加载状态下更新，避免加载过程中的滚动干扰
    if (!isLoading.value) {
        lastScrollTop.value = currentScrollTop;
    }
};


const loadMessages = async (isInitial = false) => {
    // 如果是初始加载或正在加载中，重置状态
    if (isInitial) {
        lastMsgId.value = 0;
        isFirstLoad.value = true;
    } else if (isLoading.value || !msgHasMore.value) {
        return;
    }

    if (!currentConversation.value?.id) {
        console.warn('无法加载消息：sessionId不存在');
        return;
    }

    // 检查缓存中是否已有该会话的详情数据
    const conversationId = currentConversation.value.id;
    // 使用getter方法获取缓存数据，这会自动更新访问时间
    const cachedDetail = conversationStore.getConversationDetail(conversationId);


    // 如果是初始加载且有缓存，直接使用缓存数据
    if (isInitial && cachedDetail && cachedDetail.messages) {
        msgList.value = cachedDetail.messages;
        msgHasMore.value = cachedDetail.hasMore || false;
        if (cachedDetail.messages.length > 0) {
            lastMsgId.value = cachedDetail.messages[0].id;
        }
        nextTick(() => {
            isFirstLoad.value = false;
            onScrollMsgBottom();
        });
        return;
    }

    // 无缓存或需要加载更多，调用API获取
    isLoading.value = true;
    let oldScrollHeight = 0;
    const scrollElement = msgListRef.value;

    if (!isInitial && scrollElement) {
        oldScrollHeight = scrollElement.scrollHeight;
    }

    try {
        const res = await ApiChat.getChatMessageList(
            conversationId,
            msgPageSize.value,
            lastMsgId.value
        );

        let list = res.data.items || [];

        if (list && Array.isArray(list) && list.length > 0) {
            const newMessages = list.reverse().map(item => {
                if (item.role === MSG_ROLE_USER) {
                    return onSendParseMsg(item);
                } else {
                    return onAIParseMsg(item, false);
                }
            });
            console.log('newMessages', newMessages);
            // 如果是初始加载，替换现有消息；否则添加到顶部
            if (isInitial) {
                lastMsgId.value = newMessages[0].id;
                msgList.value = newMessages;
                // 缓存初始加载的详情数据，包含分页信息
                conversationStore.cacheConversationDetail(conversationId, newMessages, res.data.has_more, newMessages.length > 0 ? newMessages[0].id : null);
            } else {
                msgList.value = [...newMessages, ...msgList.value];
                // 更新缓存数据，包含分页信息
                conversationStore.cacheConversationDetail(conversationId, msgList.value, res.data.has_more, newMessages.length > 0 ? newMessages[0].id : null);
                lastMsgId.value = newMessages[0].id;
            }

            // 判断是否还有更多数据
            msgHasMore.value = res.data.has_more;

            // 使用nextTick确保DOM已更新
            nextTick(() => {
                if (isInitial) {
                    // 初始加载时滚动到底部
                    isFirstLoad.value = false;
                    onScrollMsgBottom();
                } else if (scrollElement) {
                    // 加载更多时保持滚动位置，防止页面跳动
                    const newScrollHeight = scrollElement.scrollHeight;
                    scrollElement.scrollTop = newScrollHeight - oldScrollHeight;
                }
            });
        } else {
            // 没有数据或数据格式不正确
            msgHasMore.value = false;
            if (isInitial) {
                msgList.value = []; // 清空消息列表
                // 缓存空数组，表示该会话没有消息
                conversationStore.cacheConversationDetail(conversationId, [], false, null);
            }
        }
    } catch (error) {
        console.error('加载消息失败:', error);
    } finally {
        isLoading.value = false;
    }
};

// 防抖函数
const debounce = (fn, delay) => {
    let timer = null;
    return function(...args) {
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => {
            fn.apply(this, args);
        }, delay);
    };
};

const handleHoverConversationImpl = async (conversation) => {
    if (!conversation || currentConversation.value?.id === conversation.id) return;

    currentConversation.value = conversation;
    loadMessages(true);
};

const handleHoverConversation = debounce(handleHoverConversationImpl, 100);

const searchText = ref('');
const filteredConversations = computed(() => {
    if (!searchText.value) return conversations.value;
    return conversations.value.filter(c => c.title.toLowerCase().includes(searchText.value.toLowerCase()));
});

/**
 * 将会话按时间分组，正确处理UTC时间转换
 */
const conversationGroups = computed(() => {
    // 为每个会话添加格式化的时间，使用UTC时间处理函数
    const conversationsWithTime = filteredConversations.value.map(c => ({
        ...c,
        time: formatRelativeTimeFromUtc(c.created_at)
    }));

    // 分组函数
    const groupConversations = (conversations) => {
        const today = [];
        const yesterday = [];
        const lastWeek = [];
        const thisYear = [];

        conversations.forEach(c => {
            // 使用UTC时间处理函数检查时间范围
            if (isWithinDaysFromUtc(c.created_at, 1)) {
                // 24小时内
                today.push(c);
            } else if (isWithinDaysFromUtc(c.created_at, 2) && !isWithinDaysFromUtc(c.created_at, 1)) {
                // 1-2天内（昨天）
                yesterday.push(c);
            } else if (isWithinDaysFromUtc(c.created_at, 7) && !isWithinDaysFromUtc(c.created_at, 2)) {
                // 2-7天内
                lastWeek.push(c);
            } else {
                // 检查是否在今年
                try {
                    let utcTime = c.created_at;
                    let timeString = utcTime.trim();

                    if (!/[+-]\d{2}:?\d{2}|Z$/i.test(timeString)) {
                        timeString += 'Z';
                    }

                    const date = new Date(timeString);
                    const now = new Date();
                    const startOfYear = new Date(now.getFullYear(), 0, 1).getTime();

                    if (!isNaN(date.getTime()) && date.getTime() >= startOfYear) {
                        thisYear.push(c);
                    }
                } catch (error) {
                    console.error('Error processing conversation date:', error);
                    // 出错时放入thisYear分组
                    thisYear.push(c);
                }
            }
        });

        // 返回非空的分组
        const groups = [];
        if (today.length > 0) {
            groups.push({ type: 'today', label: t('today'), list: today });
        }
        if (yesterday.length > 0) {
            groups.push({ type: 'yesterday', label: t('yesterday'), list: yesterday });
        }
        if (lastWeek.length > 0) {
            groups.push({ type: 'lastWeek', label: t('lastWeek'), list: lastWeek });
        }
        if (thisYear.length > 0) {
            groups.push({ type: 'thisYear', label: t('thisYear'), list: thisYear });
        }

        return groups;
    };

    return groupConversations(conversationsWithTime);
});

// 监听登录状态变化
watch(() => userStore.isLoggedIn, (newLoginStatus, oldLoginStatus) => {
    // 当登录状态发生变化时，重置会话历史加载状态
    if (newLoginStatus !== oldLoginStatus) {
        conversationStore.resetHistoryLoadState();
        if (newLoginStatus) {
            loadData(true);
        } else {
            conversations.value = [];
            currentConversation.value = null;
            msgList.value = [];
        }
    }
});


// 状态变量
const deleteDialogVisible = ref(false);
const conversationToDelete = ref(null);
const editingTitle = ref('');
const editingId = ref(null);
const editingInput = ref(null);

const props = defineProps({
    isExpanded: {
        type: Boolean,
        default: false
    }
});

const emit = defineEmits(['onToggleExpand', 'onUpdateVisible']);

const clearSearch = () => {
    searchText.value = '';
};

const confirmDelete = async () => {
    deleteDialogVisible.value = false;

    if (conversationToDelete.value) {
        const index = conversations.value.findIndex(c => c.id === conversationToDelete.value.id);
        if (index !== -1) {
            conversations.value.splice(index, 1);
        }

        // 如果删除的是当前会话，则重置当前会话
        if (currentConversation.value?.id == conversationToDelete.value.id) {
            currentConversation.value = null;
            conversationStore.setCurrentConversationId(null);
        }

        try {
            const res = await ApiChat.deleteSession(conversationToDelete.value.id);
            if (res.code == 200) {
                conversationStore.deleteConversation(conversationToDelete.value.id);
                conversationToDelete.value = null;
                msgList.value = [];
                routerReplace(ROUTER_PATHS.HOME);
            }
        } catch (error) {
            loadData(true);
            console.error(error);
        }
    }
};

const clearEditTitle = () => {
    isEditing.value = false;
    editingId.value = null;
    editingTitle.value = '';
};

const confirmEdit = async (conversation) => {
    if (editingId.value && editingTitle.value.trim().length === 0) {
        return;
    }

    let saveTitle = conversation.title;
    if (editingTitle.value.trim()) {
        conversation.title = editingTitle.value.trim();
    }
    isEditing.value = false;
    editingId.value = null;
    editingTitle.value = '';

    try {
        const res = await ApiChat.updateSession({
            id: conversation.id,
            update: {
                title: conversation.title
            }
        });
        if (res.code != 200) {
            conversation.title = saveTitle;
        } else {
            // 更新store中的会话标题
            conversationStore.updateConversationTitle(conversation.id, conversation.title);
            loadData(true);
        }
    } catch (error) {
        conversation.title = saveTitle;
        console.error(error);
    }
};

const clickToggleExpand = () => {
    emit('onToggleExpand', !props.isExpanded);
};

// 组件挂载时加载初始数据
onMounted(() => {
    // 只有在用户已登录时才加载会话历史
    if (!isLoggedIn) {
        console.log('用户未登录，跳过会话历史加载');
        return;
    }

    // 检查是否已加载过会话历史
    if (conversationStore.hasLoadedHistory) {
        const storeConversations = conversationStore.conversations;
        if (storeConversations.length > 0) {
            conversations.value = storeConversations;
            lastId.value = conversationStore.page;
            hasMore.value = conversationStore.hasMore;
        } else {
            loadData(true);
        }
    } else {
        // 未加载过会话历史，主动请求接口
        loadData(true);
    }
});
</script>


<style scoped lang="scss">
.conversation-sidebar {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
}

.sidebar-container {
    display: flex;
    flex-direction: column;
    height: calc(100% - 164px);
}

