<template>
    <el-dialog v-if="!isShowDrawer" :model-value="visible" :width="isExpanded ? '85%' : '35%'" @close="emits('update:visible', false)"
        :show-close="false" top="7.5vh" destroy-on-close append-to-body center class="conversation-dialog">
        <div class="conversation-view">
            <conversation-content :is-expanded="isExpanded" @onToggleExpand="onToggleExpand" @onUpdateVisible="onUpdateVisible" />
        </div>
    </el-dialog>
    <el-drawer v-else :model-value="visible" size="90%" direction="btt"  class="conversation-drawer" @close="emits('update:visible', false)">
        <div class="conversation-view">
            <conversation-content :is-expanded="isExpanded" @onToggleExpand="onToggleExpand" @onUpdateVisible="onUpdateVisible" />
        </div>
    </el-drawer>
</template>

<script setup>
import { ref,computed ,watch} from 'vue';
import ConversationContent from './coms/conversation-content.vue';
import { useDeviceDetection } from '@/utils/device-detector';
const props = defineProps({
    visible: {
        type: Boolean,
        required: true
    }
});

const isExpanded = ref(true);
const { isMobile,windowWidth } = useDeviceDetection();
const isShowDrawer = ref(false);
const emits = defineEmits(['update:visible']);

watch(isMobile, (newVal) => {
  isShowDrawer.value = newVal;
}, { immediate: true });

watch(windowWidth, (newVal) => {
  console.log(newVal);
}, { immediate: true });

const onUpdateVisible = (value) => {    
  console.log(value);
  
    emits('update:visible', value);
};
 
const onToggleExpand = (value) => {
    isExpanded.value = value;
};
</script>

