<template>
  <div class="message-retry-container">
    <!-- 错误图标区域 -->
    <div class="error-icon-area">
      <div class="error-icon">
        <l-img src="/static/images/msg-error.png" w='20px' h='20px' />
      </div>
    </div>

    <!-- 文本信息区域 -->
    <div class="text-info-area">
      <div class="error-title">{{ $t('messageFailedTitle', { appName }) }}</div>
      <div class="error-suggestion">{{ $t('messageFailedSuggestion') }}</div>
    </div>

    <!-- 重试按钮区域 -->
    <div @click="clickRetry" class="retry-button-area">
      <l-img src="/static/images/msg-ratry.png" w='16px' h='16px' />
      <span>{{ $t('retry') }}</span>
    </div>
  </div>
</template>

<script setup>
import { ref } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';

const { t } = useI18n();

// 获取应用名称
const appName = ref(import.meta.env.VITE_APP_TITLE);

// 组件props
const props = defineProps({
  // 重试状态
  isRetrying: {
    type: Boolean,
    default: false
  }
});

// 组件事件
const emit = defineEmits(['onRetry']);

// 重试点击事件处理
const clickRetry = () => {
  console.log('clickRetry',props.isRetrying);
  
  if (!props.isRetrying) {
    emit('onRetry');
  }
};
</script>

